'use client';
import Link from 'next/link';import {ArrowLeft,Minus,Plus,ShoppingBag,Trash2,Zap} from 'lucide-react';import {useCart} from '../CartContext';import {products} from '../products';
const amount=(price:string)=>Number(price.replace(/\D/g,''));const money=(n:number)=>new Intl.NumberFormat('hu-HU').format(n)+' Ft';
export default function CartPage(){const {items,count,remove,setQty}=useCart();const lines=items.map(x=>({line:x,p:products.find(p=>p.slug===x.slug)!})).filter(x=>x.p);const total=lines.reduce((s,x)=>s+amount(x.p.price)*x.line.qty,0);
return <main className="cartPage"><header className="productTop"><Link href="/#termekek" className="backLink"><ArrowLeft/> Vásárlás folytatása</Link><Link className="productBrand" href="/"><span><Zap/></span><b>Töltés<em>Otthon</em></b></Link></header><section className="wrap cartWrap"><div className="cartTitle"><span className="kicker">KOSÁR</span><h1>A kiválasztott töltőid</h1><p>{count} db termék a kosárban</p></div>{lines.length===0?<div className="emptyCart"><ShoppingBag/><h2>A kosarad még üres</h2><p>Válassz az autódhoz és otthonodhoz megfelelő töltőt.</p><Link className="btn" href="/#termekek">Töltők megtekintése →</Link></div>:<div className="cartGrid"><div className="cartLines">{lines.map(({line,p})=><article className="cartLine" key={p.slug}><div className="cartThumb"><Zap/></div><div className="cartProduct"><small>{String(p.power).replace('.',',')} kW · {p.connector}</small><h2><Link href={`/termekek/${p.slug}`}>{p.name}</Link></h2><span className="stock">● {p.stock?'Raktáron':'Rendelésre'}</span></div><div className="qty"><button onClick={()=>setQty(p.slug,line.qty-1)} aria-label="Mennyiség csökkentése"><Minus/></button><b>{line.qty}</b><button onClick={()=>setQty(p.slug,line.qty+1)} aria-label="Mennyiség növelése"><Plus/></button></div><strong className="linePrice">{money(amount(p.price)*line.qty)}</strong><button className="removeBtn" onClick={()=>remove(p.slug)} aria-label="Termék törlése"><Trash2/></button></article>)}</div><aside className="cartSummary"><h2>Összesítés</h2><p><span>Termékek</span><b>{money(total)}</b></p><p><span>Szállítás</span><b>Következő lépésben</b></p><div className="cartTotal"><span>Végösszeg</span><strong>{money(total)}</strong><small>bruttó összeg</small></div><Link className="btn checkoutBtn" href="/penztar">Tovább a rendeléshez →</Link><small>A következő oldalon megadhatod a rendelési és telepítési adatokat.</small></aside></div>}</section></main>}
